<script setup>
import {ref} from 'vue'; import AdminLayout from '../layouts/AdminLayout.vue'; import PageHeader from '../components/PageHeader.vue'; import {store,persist} from '../mockStore'
const tab=ref('parts'),part=ref({name:'',supplier:'Proveedor A',cost:0,stock:0}),supplier=ref({name:'',contact:'',phone:'',email:''})
function addPart(){if(!part.value.name)return;store.parts.push({id:Date.now(),...part.value});persist();part.value={name:'',supplier:'Proveedor A',cost:0,stock:0}}
function addSupplier(){if(!supplier.value.name)return;store.suppliers.push({id:Date.now(),...supplier.value});persist();supplier.value={name:'',contact:'',phone:'',email:''}}
</script>
<template><AdminLayout><PageHeader>Repuestos y proveedores<template #subtitle>Catálogo simplificado para el prototipo visual.</template></PageHeader><div class="section-tabs mb-3"><button :class="{active:tab==='parts'}" @click="tab='parts'">Repuestos</button><button :class="{active:tab==='suppliers'}" @click="tab='suppliers'">Proveedores</button></div><div v-if="tab==='parts'" class="row g-3"><div class="col-lg-8"><div class="mc-card p-3 table-responsive"><table class="table mb-0"><thead><tr><th>Repuesto</th><th>Proveedor</th><th>Costo ref.</th><th>Stock</th></tr></thead><tbody><tr v-for="p in store.parts"><td>{{p.name}}</td><td>{{p.supplier}}</td><td>${{Number(p.cost).toLocaleString('es-CL')}}</td><td>{{p.stock}}</td></tr></tbody></table></div></div><div class="col-lg-4"><div class="mc-card p-3"><h6>Nuevo repuesto demo</h6><input v-model="part.name" class="form-control mb-2" placeholder="Descripción"><select v-model="part.supplier" class="form-select mb-2"><option v-for="s in store.suppliers">{{s.name}}</option></select><input v-model.number="part.cost" type="number" min="0" class="form-control mb-2" placeholder="Costo"><input v-model.number="part.stock" type="number" min="0" class="form-control mb-2" placeholder="Stock"><button class="btn btn-primary" @click="addPart">Agregar</button></div></div></div><div v-else class="row g-3"><div class="col-lg-8"><div class="mc-card p-3 table-responsive"><table class="table mb-0"><thead><tr><th>Proveedor</th><th>Contacto</th><th>Teléfono</th><th>Correo</th></tr></thead><tbody><tr v-for="s in store.suppliers"><td>{{s.name}}</td><td>{{s.contact}}</td><td>{{s.phone}}</td><td>{{s.email}}</td></tr></tbody></table></div></div><div class="col-lg-4"><div class="mc-card p-3"><h6>Nuevo proveedor demo</h6><input v-model="supplier.name" class="form-control mb-2" placeholder="Nombre"><input v-model="supplier.contact" class="form-control mb-2" placeholder="Contacto"><input v-model="supplier.phone" class="form-control mb-2" placeholder="Teléfono"><input v-model="supplier.email" class="form-control mb-2" placeholder="Correo"><button class="btn btn-primary" @click="addSupplier">Agregar</button></div></div></div></AdminLayout></template>
